class Solution:
    def longestConsecutive(self, nums):
        s = set(nums)
        best = 0
        for x in s:
            if x - 1 not in s:
                y = x
                while y in s:
                    y += 1
                best = max(best, y - x)
        return best

class Solution:
    def productExceptSelf(self, nums):
        n = len(nums)
        ans = [1] * n
        left = 1
        for i in range(n):
            left *= nums[i]
            ans[i] *= left
        right = 1
        for i in range(n - 1, -1, -1):
            right *= nums[i]
            ans[i] *= right
        return ans

