class Solution:
    def minEatingSpeed(self, piles, h):
        lo, hi = 0, max(piles)
        def ok(k):
            return sum((p + k - 1) // k for p in piles) <= h
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

